mapper.select:
SELECT COMPANY_CODE AS companyCode ,DIVISION_CODE AS divisionCode ,SALES_NO AS salesNo FROM (SELECT SM.COMPANY_CODE ,SM.DIVISION_CODE ,SM.SALES_NO ,SM.EXPORT_FLAG ,SM.CUSTOMER_CODE FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SD.SALES_NO = SM.SALES_NO AND SD.DIVISION_CODE = SM.DIVISION_CODE AND SD.COMPANY_CODE = SM.COMPANY_CODE WHERE SM.COMPANY_CODE = #{p.companyCode} AND SM.DIVISION_CODE = COALESCE(#{p.divisionCode}, SM.DIVISION_CODE) AND ((SM.EXPORT_FLAG = 'D' AND SM.VIRTUAL_YN = 'Y') OR (SM.EXPORT_FLAG = 'E' AND SM.TARGET_FTA_CODE IS NOT NULL)) AND SM.INVOICE_DATE LIKE #{p.yyyymmdd} || '%' AND SM.CUSTOMER_CODE = COALESCE(#{p.customerCode}, SM.CUSTOMER_CODE) AND SM.DELIVERY_CUSTOMER_CODE = COALESCE(#{p.deliveryCustomerCode}, SM.DELIVERY_CUSTOMER_CODE) AND SM.EXPORT_FLAG = COALESCE(#{p.exportFlag}, SM.EXPORT_FLAG)
AND SD.PRODUCT_CODE IN
#{productCode}
) X GROUP BY COMPANY_CODE, DIVISION_CODE, SALES_NO, EXPORT_FLAG, CUSTOMER_CODE ORDER BY EXPORT_FLAG, CUSTOMER_CODE
